import type {WorkspaceSql} from './workspace'
import {readCorporateInventory} from './m71'
import {M74_PROFILE,M74_LIMITATIONS,M74_METHOD,type M74Authority,type M74Register,type M74Version,type M74Review,type M74Report,type M74SaveInput,type M74ReviewInput,type M74ReportInput,type M74Calculation} from './m74-contract'
import {m74CanonicalJson,validateM74Save,validateM74Review,validateM74Report,m74Activity,m74ResolveBinding,m74SourceChoices,m74FuelStatementText,m74MileageStatementText,m74InputHashPayload,m74ContentPayload,m74VersionHashPayload,m74ReviewHashPayload,m74ReportHashPayload,m74CalculationHashPayload,m74Export,deriveM74ActivityStatus,deriveM74Findings,m74CanCalculate,m74Keys} from './m74-validation'
import {m74RenderReport,m74ReportSnapshot} from './m74-report'
import {m71Uuid} from './m71-validation'
export * from './m74-contract'
export * from './m74-validation'
export * from './m74-report'
export const m74Hash=(v:unknown)=>new Bun.CryptoHasher('sha256').update(m74CanonicalJson(v)).digest('hex')
export const m74BytesHash=(s:string)=>new Bun.CryptoHasher('sha256').update(s).digest('hex')
const bytes=(s:string)=>new TextEncoder().encode(s).length
const same=(a:unknown,b:unknown)=>m74CanonicalJson(a)===m74CanonicalJson(b)
const flags={synthetic:true as const,scope1Completeness:'incomplete' as const,corporateCompleteness:'incomplete' as const,releaseEligible:false as const,assurance:'none' as const}
const fail=():never=>{throw Error('Stored mobile-diesel workpaper could not be verified.')}
const verify=(v:unknown)=>{if(!v)fail()}
const iso=(v:string)=>{const d=new Date(v);return Number.isFinite(d.getTime())?d.toISOString():fail()}
type RequestRow={company_id:string;idempotency_key:string;actor_id:string;kind:string;fingerprint:string;record_id:string}
type AuditRow={company_id:string;record_id:string;kind:string;record_sha256:string;actor_id:string;created_at:string}
type ReservationRow={company_id:string;evidence_key:string;worksheet_id:string;statement_kind:'fuel'|'mileage';created_at:string}
export async function readMobileDiesel(tx:WorkspaceSql,companyId:string,authority:M74Authority):Promise<M74Register|null>{
 if(!(await tx.query<{allowed:boolean}>('select neuvetra.m74_lock($1,false) allowed',[companyId])).rows[0]?.allowed)return null
 const coverage=await readCorporateInventory(tx,companyId);if(!coverage)return null
 const data=(await tx.query<{heads:any[];versions:any[];fuelStatements:any[];mileageStatements:any[];reservations:ReservationRow[];reviews:any[];reports:any[];requests:RequestRow[];audits:AuditRow[]}>(`select
 coalesce((select jsonb_agg(x order by id) from neuvetra.mobile_diesel_heads x where company_id=$1),'[]') heads,
 coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('quantity_gallons',x.quantity_gallons::text,'distance_miles',x.distance_miles::text) order by worksheet_id,version) from neuvetra.mobile_diesel_versions x where company_id=$1),'[]') versions,
 coalesce((select jsonb_agg(x) from neuvetra.mobile_diesel_fuel_statements x where company_id=$1),'[]') "fuelStatements",
 coalesce((select jsonb_agg(x) from neuvetra.mobile_diesel_mileage_statements x where company_id=$1),'[]') "mileageStatements",
 coalesce((select jsonb_agg(x) from neuvetra.mobile_diesel_evidence_reservations x where company_id=$1),'[]') reservations,
 coalesce((select jsonb_agg(x) from neuvetra.mobile_diesel_reviews x where company_id=$1),'[]') reviews,
 coalesce((select jsonb_agg(x order by created_at,id) from neuvetra.mobile_diesel_reports x where company_id=$1),'[]') reports,
 coalesce((select jsonb_agg(x) from neuvetra.mobile_diesel_requests x where company_id=$1),'[]') requests,
 coalesce((select jsonb_agg(x) from neuvetra.mobile_diesel_audit x where company_id=$1),'[]') audits`,[companyId])).rows[0]!
 verify(data.heads.length<=3&&data.versions.length<=40&&data.audits.length===data.versions.length+data.reviews.length+data.reports.length&&data.requests.length===data.audits.length)
 const audit=(kind:string,id:string,hash:string,actor:string,time:string,worksheetId:string|null,request:unknown)=>{const rows=data.audits.filter(a=>a.kind===kind&&a.record_id===id),req=data.requests.filter(r=>r.kind===kind&&r.record_id===id);verify(rows.length===1&&req.length===1);const a=rows[0]!,r=req[0]!;verify(a.company_id===companyId&&a.actor_id===actor&&a.record_sha256===hash&&iso(a.created_at)===time&&r.company_id===companyId&&r.actor_id===actor&&m71Uuid(r.idempotency_key)&&r.fingerprint===m74Hash({operation:kind,actor,companyId,worksheetId,request}))}
 const all:M74Version[]=[]
 const expectedReservations=new Set<string>()
 const worksheets:M74Register['worksheets']=[]
 for(const head of data.heads){verify(head.company_id===companyId&&m71Uuid(head.id)&&m71Uuid(head.source_id));const versions:M74Version[]=[]
  for(const row of data.versions.filter(r=>r.worksheet_id===head.id)){
   const v=structuredClone(row.payload) as M74Version,prior=versions[versions.length-1]
   try{m74Keys(v,['id','companyId','worksheetId','version','previousVersionId','previousVersionSha256','createdBy','createdAt','contributorIds','correctionReason','activity','activityStatus','coverageVersion','fuelStatement','mileageStatement','calculation','findings','inputSha256','contentSha256','versionSha256','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance','review'])}catch{return fail()}
   verify(v.id===row.id&&m71Uuid(v.id)&&v.companyId===companyId&&row.company_id===companyId&&v.worksheetId===head.id&&v.version===versions.length+1&&v.version===row.version&&v.previousVersionId===(prior?.id??null)&&v.previousVersionId===row.previous_version_id&&v.previousVersionSha256===(prior?.versionSha256??null)&&v.createdBy===row.created_by&&m71Uuid(v.createdBy)&&v.createdAt===iso(row.created_at)&&v.createdAt>=(prior?.createdAt??'')&&v.review===null)
   verify(Object.entries(flags).every(([k,x])=>(v as any)[k]===x)&&v.activity.binding.sourceId===head.source_id&&v.activity.vehicle.assetId===head.asset_id)
   let normalized:M74SaveInput;try{normalized=validateM74Save({...v.activity,expectedVersionId:v.previousVersionId,expectedVersionSha256:v.previousVersionSha256,correctionReason:v.correctionReason,idempotencyKey:v.id})}catch{return fail()}
   verify(same(m74Activity(normalized),v.activity));if(prior)verify(!same(prior.activity,v.activity)||prior.correctionReason!==v.correctionReason)
   const cv=coverage.versions.find(x=>x.id===v.activity.binding.coverageVersionId);verify(cv&&row.coverage_version_id===cv.id&&same({...cv!,review:null},v.coverageVersion));try{m74ResolveBinding(v.activity.binding,v.coverageVersion)}catch{return fail()}
   const contributors=[...new Set([...(prior?.contributorIds??[]),...v.coverageVersion.contributorIds,v.createdBy])].sort();verify(same(v.contributorIds,contributors)&&same(v.activityStatus,deriveM74ActivityStatus(v.activity))&&same(v.findings,deriveM74Findings(v.activity)))
   const verifyStatement=(kind:'fuel'|'mileage')=>{const input=kind==='fuel'?v.activity.fuelStatement:v.activity.mileageStatement,statement=kind==='fuel'?v.fuelStatement:v.mileageStatement,rowId=kind==='fuel'?row.fuel_statement_id:row.mileage_statement_id,rows=kind==='fuel'?data.fuelStatements:data.mileageStatements;if(input===null){verify(statement===null&&rowId===null);return}verify(statement&&rowId===statement.id&&m71Uuid(statement.id));const matches=rows.filter(x=>x.id===statement!.id);verify(matches.length===1);const stored=matches[0];let text:string;try{text=kind==='fuel'?m74FuelStatementText(v.activity,v.coverageVersion):m74MileageStatementText(v.activity,v.coverageVersion)}catch{return fail()}const profile=kind==='fuel'?'m74-synthetic-fuel-statement-v1':'m74-synthetic-mileage-statement-v1',locator=`m74-${kind}-statement:${statement!.id}:annual-activity`,evidenceKey=m74Hash([input.issuer.toLowerCase(),input.reference.toLowerCase(),'2025']),reservation=data.reservations.filter(x=>x.evidence_key===evidenceKey);expectedReservations.add(evidenceKey);verify(reservation.length===1&&reservation[0]!.company_id===companyId&&reservation[0]!.worksheet_id===head.id&&reservation[0]!.statement_kind===kind&&iso(reservation[0]!.created_at)<=v.createdAt);verify(same(statement,{id:statement!.id,profile,input,locator,text,sha256:m74BytesHash(text),byteLength:bytes(text)})&&same(stored.payload,statement)&&stored.company_id===companyId&&stored.statement_text===text&&stored.statement_sha256===statement!.sha256)}
   verifyStatement('fuel');verifyStatement('mileage')
   verify(row.quantity_gallons===v.activity.quantityGallons&&row.distance_miles===v.activity.distanceMiles)
   if(!m74CanCalculate(v.activity))verify(v.calculation===null);else{const c=v.calculation;verify(c&&same(c.method,M74_METHOD)&&same(c.input,{binding:v.activity.binding,period:v.activity.period,vehicle:v.activity.vehicle,quantityGallons:v.activity.quantityGallons,quantityUnit:'US_gallon',distanceMiles:v.activity.distanceMiles,distanceUnit:'vehicle_mile',fuelStatementSha256:v.fuelStatement!.sha256,mileageStatementSha256:v.mileageStatement!.sha256})&&c.inputSha256===m74Hash(c.input)&&c.resultSha256===m74Hash(m74CalculationHashPayload(c)))}
   verify(v.inputSha256===row.input_sha256&&v.inputSha256===m74Hash(m74InputHashPayload(v))&&v.contentSha256===row.content_sha256&&v.contentSha256===m74Hash(m74ContentPayload(v))&&v.versionSha256===row.version_sha256&&v.versionSha256===m74Hash(m74VersionHashPayload(v))&&row.export_text===m74Export(v))
   audit('save',v.id,v.versionSha256,v.createdBy,v.createdAt,prior?head.id:null,{...v.activity,expectedVersionId:v.previousVersionId,expectedVersionSha256:v.previousVersionSha256,correctionReason:v.correctionReason})
   const reviews=data.reviews.filter(r=>r.version_id===v.id);verify(reviews.length<=1);if(reviews[0]){const rr=reviews[0],r=rr.payload as M74Review;try{m74Keys(r,['id','versionId','versionSha256','decision','note','acknowledgedLimitations','reviewerId','reviewedAt','decisionSha256']);validateM74Review({versionId:r.versionId,expectedVersionSha256:r.versionSha256,decision:r.decision,note:r.note,acknowledgedLimitations:r.acknowledgedLimitations,idempotencyKey:r.id})}catch{return fail()}
    verify(r.id===rr.id&&rr.company_id===companyId&&r.versionId===v.id&&r.versionSha256===v.versionSha256&&r.reviewerId===rr.reviewed_by&&m71Uuid(r.reviewerId)&&!v.contributorIds.includes(r.reviewerId)&&r.reviewedAt===iso(rr.reviewed_at)&&r.reviewedAt>=v.createdAt&&r.decisionSha256===rr.decision_sha256&&r.decisionSha256===m74Hash(m74ReviewHashPayload(companyId,r))&&(r.decision!=='accepted_bounded_internal'||v.calculation!==null));audit('review',r.id,r.decisionSha256,r.reviewerId,r.reviewedAt,head.id,{versionId:v.id,expectedVersionSha256:v.versionSha256,decision:r.decision,note:r.note,acknowledgedLimitations:r.acknowledgedLimitations});v.review=r
   }versions.push(v);all.push(v)
  }
  verify(versions.length>0&&head.version_id===versions[versions.length-1]!.id&&head.revision===versions.length)
  const last=versions[versions.length-1]!,vehicleKey=m74Hash([last.activity.vehicle.assetId,'Fossil Diesel','2025']),fuelReference=last.activity.fuelStatement?m74Hash([last.activity.fuelStatement.issuer.toLowerCase(),last.activity.fuelStatement.reference.toLowerCase(),'2025']):null,mileageReference=last.activity.mileageStatement?m74Hash([last.activity.mileageStatement.issuer.toLowerCase(),last.activity.mileageStatement.reference.toLowerCase(),'2025']):null;verify(head.asset_id===last.activity.vehicle.assetId&&head.vehicle_key===vehicleKey&&head.fuel_reference_key===fuelReference&&head.mileage_reference_key===mileageReference)
  const reports:M74Report[]=[];for(const row of data.reports.filter(r=>r.worksheet_id===head.id)){const r=row.payload as M74Report;try{m74Keys(r,['id','companyId','worksheetId','versionId','versionSha256','decisionId','decisionSha256','createdBy','createdAt','rendererVersion','html','htmlSha256','htmlByteLength','snapshotJson','snapshotSha256','reportSha256'])}catch{return fail()}const v=versions.find(v=>v.id===r.versionId);verify(v&&r.id===row.id&&m71Uuid(r.id)&&r.companyId===companyId&&row.company_id===companyId&&r.worksheetId===head.id&&row.version_id===v.id&&r.versionSha256===v.versionSha256&&r.createdBy===row.created_by&&m71Uuid(r.createdBy)&&r.createdAt===iso(row.created_at)&&r.createdAt>=v.createdAt&&r.rendererVersion==='m74-mobile-source-report-v1');const decision=r.decisionId===null?null:v!.review;verify(r.decisionId===row.decision_id&&(r.decisionId===null?r.decisionSha256===null:decision&&decision.id===r.decisionId&&decision.decisionSha256===r.decisionSha256&&r.createdAt>=decision.reviewedAt));const snapshot=m74ReportSnapshot(v!,decision),text=m74CanonicalJson(snapshot),html=m74RenderReport(snapshot);verify(r.snapshotJson===text&&r.snapshotSha256===m74BytesHash(text)&&r.html===html&&r.htmlSha256===m74BytesHash(html)&&r.htmlByteLength===bytes(html)&&r.reportSha256===row.report_sha256&&r.reportSha256===m74Hash(m74ReportHashPayload(r)));audit('report',r.id,r.reportSha256,r.createdBy,r.createdAt,head.id,{versionId:r.versionId,expectedVersionSha256:r.versionSha256,expectedDecisionId:r.decisionId,expectedDecisionSha256:r.decisionSha256});reports.push(r)}
  worksheets.push({profile:M74_PROFILE,companyId,worksheetId:head.id,sourceId:head.source_id,vehicleAssetId:head.asset_id,headVersionId:head.version_id,versions,reports,findings:last.activity.binding.coverageVersionId!==coverage.headVersionId?[{code:'coverage_head_changed',message:'Corporate coverage changed; relink this source before a new review or report.'}]:[],limitations:[...M74_LIMITATIONS],...flags})
 }
 verify(all.length===data.versions.length&&data.fuelStatements.length===all.filter(v=>v.fuelStatement).length&&data.mileageStatements.length===all.filter(v=>v.mileageStatement).length&&data.reservations.length===expectedReservations.size&&data.reservations.every(r=>expectedReservations.has(r.evidence_key))&&data.reviews.every(r=>all.some(v=>v.id===r.version_id))&&data.reports.every(r=>worksheets.some(w=>w.worksheetId===r.worksheet_id)))
 await authority.replayBatch(all.flatMap(v=>v.calculation?[v.calculation]:[]))
 const head=coverage.versions[coverage.versions.length-1],result:M74Register={profile:M74_PROFILE,companyId,coverageHeadVersionId:coverage.headVersionId,worksheets,sources:head?m74SourceChoices(head):[],coverageFindings:head?.findings??[],limitations:[...M74_LIMITATIONS],...flags};verify(bytes(m74CanonicalJson(result))<=4000000);return result
}
async function locked(tx:WorkspaceSql,companyId:string){if(!(await tx.query<{allowed:boolean}>('select neuvetra.m74_lock($1,true) allowed',[companyId])).rows[0]?.allowed)throw Object.assign(Error('Forbidden.'),{code:'42501'})}
export async function saveMobileDiesel(tx:WorkspaceSql,actor:string,companyId:string,worksheetId:string|null,value:M74SaveInput,authority:M74Authority){const input=validateM74Save(value);await locked(tx,companyId);const before=await readMobileDiesel(tx,companyId,authority);if(!before)return fail();const priorRequest=(await tx.query<RequestRow>('select * from neuvetra.mobile_diesel_requests where company_id=$1 and idempotency_key=$2',[companyId,input.idempotencyKey])).rows[0];if(priorRequest){const {idempotencyKey:_,...request}=input;if(priorRequest.fingerprint!==m74Hash({operation:'save',actor,companyId,worksheetId,request})||priorRequest.kind!=='save')throw Object.assign(Error('Idempotency conflict.'),{code:'23505'});const v=before.worksheets.flatMap(w=>w.versions).find(v=>v.id===priorRequest.record_id);return v?{...v,review:null}:fail()}
 const coverage=await readCorporateInventory(tx,companyId),cv=coverage?.versions[coverage.versions.length-1];if(!cv||cv.id!==input.binding.coverageVersionId||cv.versionSha256!==input.binding.coverageVersionSha256)throw Object.assign(Error('Coverage changed.'),{code:'23505'});m74ResolveBinding(input.binding,cv)
 const activity=m74Activity(input);let calculation:M74Calculation|null=null;if(m74CanCalculate(activity)){calculation=await authority.calculate({binding:activity.binding,period:activity.period,vehicle:activity.vehicle,quantityGallons:activity.quantityGallons!,quantityUnit:'US_gallon',distanceMiles:activity.distanceMiles!,distanceUnit:'vehicle_mile',fuelStatementSha256:m74BytesHash(m74FuelStatementText(activity,cv)),mileageStatementSha256:m74BytesHash(m74MileageStatementText(activity,cv))})}
 const id=(await tx.query<{id:string}>('select neuvetra.save_mobile_diesel($1,$2,$3::text::jsonb,$4::text::jsonb) id',[companyId,worksheetId,JSON.stringify(input),JSON.stringify(calculation)])).rows[0]!.id;const after=await readMobileDiesel(tx,companyId,authority);const v=after?.worksheets.flatMap(w=>w.versions).find(v=>v.id===id);return v?{...v,review:null}:fail()
}
export async function reviewMobileDiesel(tx:WorkspaceSql,companyId:string,worksheetId:string,input:M74ReviewInput,authority:M74Authority){await locked(tx,companyId);await readMobileDiesel(tx,companyId,authority);const id=(await tx.query<{id:string}>('select neuvetra.review_mobile_diesel($1,$2,$3::text::jsonb) id',[companyId,worksheetId,JSON.stringify(validateM74Review(input))])).rows[0]!.id;const after=await readMobileDiesel(tx,companyId,authority);return after?.worksheets.flatMap(w=>w.versions).map(v=>v.review).find(r=>r?.id===id)??fail()}
export async function createMobileDieselReport(tx:WorkspaceSql,companyId:string,worksheetId:string,input:M74ReportInput,authority:M74Authority){await locked(tx,companyId);await readMobileDiesel(tx,companyId,authority);const id=(await tx.query<{id:string}>('select neuvetra.create_mobile_diesel_report($1,$2,$3::text::jsonb) id',[companyId,worksheetId,JSON.stringify(validateM74Report(input))])).rows[0]!.id;const after=await readMobileDiesel(tx,companyId,authority);return after?.worksheets.flatMap(w=>w.reports).find(r=>r.id===id)??fail()}

import type {M71Finding,M71Version} from './m71-contract'

export const M74_PROFILE='synthetic-mobile-diesel-v1' as const
export const M74_PERIOD={start:'2025-01-01',endExclusive:'2026-01-01'} as const
export const M74_LIMITATIONS=['synthetic_only','scope1_incomplete','corporate_inventory_incomplete','factor_and_method_not_released','vehicle_mobile_combustion_subtotal_only','upstream_fuel_emissions_excluded','requirements_not_determined','no_external_assurance'] as const
export const M74_MAX_STREAMS=3, M74_MAX_VERSIONS=40, M74_MAX_HISTORY_BYTES=3800000, M74_MAX_RESPONSE_BYTES=4000000

export type M74Period=typeof M74_PERIOD
export interface M74BindingInput {coverageVersionId:string;coverageVersionSha256:string;entityId:string;facilityId:string;sourceId:string;boundaryDecisionId:string}
export interface M74VehicleInput {assetId:string;vehicleClass:'Medium- and Heavy-Duty Vehicles';classificationBasis:string;modelYear:number;fuel:'Fossil Diesel';controlBasis:'owned_operational_control_full_year'}
export interface M74FuelStatementInput {issuer:string;reference:string;statedQuantityGallons:string;description:string;consumptionBasis:'dedicated_vehicle_consumed_no_adjustments'}
export interface M74MileageStatementInput {issuer:string;reference:string;statedDistanceMiles:string;description:string;distanceBasis:'dedicated_vehicle_annual_distance'}
export interface M74SaveInput {profile:typeof M74_PROFILE;binding:M74BindingInput;period:M74Period;vehicle:M74VehicleInput;quantityGallons:string|null;distanceMiles:string|null;fuelStatement:M74FuelStatementInput|null;mileageStatement:M74MileageStatementInput|null;fuelManualConfirmation:boolean;mileageManualConfirmation:boolean;fuelDiscrepancyReason:string|null;mileageDiscrepancyReason:string|null;zeroReason:string|null;expectedVersionId:string|null;expectedVersionSha256:string|null;correctionReason:string|null;idempotencyKey:string}
export interface M74ReviewInput {versionId:string;expectedVersionSha256:string;decision:'accepted_bounded_internal'|'changes_requested';note:string;acknowledgedLimitations:string[];idempotencyKey:string}
export interface M74ReportInput {versionId:string;expectedVersionSha256:string;expectedDecisionId:string|null;expectedDecisionSha256:string|null;idempotencyKey:string}
export type M74Activity=Omit<M74SaveInput,'expectedVersionId'|'expectedVersionSha256'|'correctionReason'|'idempotencyKey'>
export type M74DimensionStatus='missing'|'evidence_missing'|'unconfirmed'|'explicit_zero'|'entered'|'discrepancy'
export interface M74ActivityStatus {fuel:M74DimensionStatus;mileage:M74DimensionStatus}
export interface M74AuthorityInput {binding:M74BindingInput;period:M74Period;vehicle:M74VehicleInput;quantityGallons:string;quantityUnit:'US_gallon';distanceMiles:string;distanceUnit:'vehicle_mile';fuelStatementSha256:string;mileageStatementSha256:string}
export interface M74Method {id:'mobile-diesel-combustion';version:'m74-development-v1';engineSha256:string;sourceSha256:string;factorSha256:string;gwpSha256:string;sourceTitle:string;sourceSheet:string;factorCells:string[];gwpCells:string[];noteCells:string[];co2KgPerGallon:string;ch4GramsPerMile:string;n2oGramsPerMile:string;ch4Gwp:string;n2oGwp:string;gwpAssessment:string;status:'development_candidate_not_released';releaseEligible:false;rights:'unresolved_for_factor_release'}
export const M74_METHOD:M74Method={id:'mobile-diesel-combustion',version:'m74-development-v1',engineSha256:'1dc0bb7249d91e854004a8cadd34068be3fc03ecdd6e10b4cf297d375d7f52a6',sourceSha256:'43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7',factorSha256:'416931c40b347f1e22e9d4019ca1c28bd27ce40d7c16a3beeac3dadbbb783187',gwpSha256:'c151f9b90b23eba7ee9d36dd57a851ecf7a6f200c915579819b683d2b3b3c1c7',sourceTitle:'EPA GHG Emission Factors Hub 2025',sourceSheet:'Emission Factors Hub',factorCells:['C103:E103','C107:E107','C255:G256'],gwpCells:['E523:E526'],noteCells:['F3','F248:G248','C255:D256'],co2KgPerGallon:'10.21',ch4GramsPerMile:'0.0095',n2oGramsPerMile:'0.0431',ch4Gwp:'28',n2oGwp:'265',gwpAssessment:'IPCC AR5 100-year',status:'development_candidate_not_released',releaseEligible:false,rights:'unresolved_for_factor_release'}
export interface M74Gas {mass:string;massUnit:string;co2e:string;co2eUnit:'kg CO2e'}
export interface M74Calculation {profile:'m74-decimal-result-v1';input:M74AuthorityInput;inputSha256:string;method:M74Method;gasResults:{co2:M74Gas;ch4:M74Gas;n2o:M74Gas};total:{unrounded:string;display:string;unit:'kg CO2e';rounding:'half_even_4dp'};resultSha256:string}
export interface M74Authority {calculate(input:M74AuthorityInput):Promise<M74Calculation>;replayBatch(records:M74Calculation[]):Promise<void>}
export interface M74FuelStatement {id:string;profile:'m74-synthetic-fuel-statement-v1';input:M74FuelStatementInput;locator:string;text:string;sha256:string;byteLength:number}
export interface M74MileageStatement {id:string;profile:'m74-synthetic-mileage-statement-v1';input:M74MileageStatementInput;locator:string;text:string;sha256:string;byteLength:number}
export interface M74Review {id:string;versionId:string;versionSha256:string;decision:M74ReviewInput['decision'];note:string;acknowledgedLimitations:string[];reviewerId:string;reviewedAt:string;decisionSha256:string}
export interface M74Finding {code:string;message:string}
export interface M74Version {id:string;companyId:string;worksheetId:string;version:number;previousVersionId:string|null;previousVersionSha256:string|null;createdBy:string;createdAt:string;contributorIds:string[];correctionReason:string|null;activity:M74Activity;activityStatus:M74ActivityStatus;coverageVersion:M71Version;fuelStatement:M74FuelStatement|null;mileageStatement:M74MileageStatement|null;calculation:M74Calculation|null;findings:M74Finding[];inputSha256:string;contentSha256:string;versionSha256:string;synthetic:true;scope1Completeness:'incomplete';corporateCompleteness:'incomplete';releaseEligible:false;assurance:'none';review:M74Review|null}
export interface M74Report {id:string;companyId:string;worksheetId:string;versionId:string;versionSha256:string;decisionId:string|null;decisionSha256:string|null;createdBy:string;createdAt:string;rendererVersion:'m74-mobile-source-report-v1';html:string;htmlSha256:string;htmlByteLength:number;snapshotJson:string;snapshotSha256:string;reportSha256:string}
export interface M74Worksheet {profile:typeof M74_PROFILE;companyId:string;worksheetId:string;sourceId:string;vehicleAssetId:string;headVersionId:string;versions:M74Version[];reports:M74Report[];findings:M74Finding[];limitations:string[];synthetic:true;scope1Completeness:'incomplete';corporateCompleteness:'incomplete';releaseEligible:false;assurance:'none'}
export interface M74SourceChoice {binding:M74BindingInput;companyLabel:string;entityLabel:string;facilityLabel:string;sourceLabel:string;eligible:boolean;findings:M74Finding[]}
export interface M74Register {profile:typeof M74_PROFILE;companyId:string;coverageHeadVersionId:string|null;worksheets:M74Worksheet[];sources:M74SourceChoice[];coverageFindings:M71Finding[];limitations:string[];synthetic:true;scope1Completeness:'incomplete';corporateCompleteness:'incomplete';releaseEligible:false;assurance:'none'}

/** Pure shared M74 contract: no database, process, filesystem, Bun or emissions arithmetic. */
import {m71CanonicalJson,m71HashString,m71Keys,m71Uuid,M71_EVIDENCE_SHA256} from './m71-validation'
import {M71_ARTIFACT,type M71Version} from './m71-contract'
import {M74_LIMITATIONS,M74_PERIOD,M74_PROFILE,type M74Activity,type M74ActivityStatus,type M74BindingInput,type M74Calculation,type M74Finding,type M74Report,type M74ReportInput,type M74Review,type M74ReviewInput,type M74SaveInput,type M74SourceChoice,type M74Version} from './m74-contract'

export const m74CanonicalJson=m71CanonicalJson
export class M74ValidationError extends Error {}
export const m74Require=(value:unknown,message='Invalid synthetic mobile-diesel request.'):void=>{if(!value)throw new M74ValidationError(message)}
export const m74Keys=(value:unknown,keys:string[])=>{try{m71Keys(value,keys)}catch{throw new M74ValidationError('Unexpected or missing mobile-diesel fields.')}}
export function m74Text(value:unknown,max=500):string{m74Require(typeof value==='string'&&value.length>0);const text=(value as string).trim().normalize('NFC');m74Require(text.length>0&&Array.from(text).length<=max&&!/[\u0000-\u001f\u007f-\u009f\ud800-\udfff]/u.test(text));return text}
export const m74NullableText=(value:unknown,max=500)=>value===null?null:m74Text(value,max)
export function m74Quantity(value:unknown):string{m74Require(typeof value==='string'&&/^(?:0|[1-9][0-9]{0,11})(?:\.[0-9]{1,3})?$/.test(value));const [whole,fraction='']=(value as string).split('.');return whole+'.'+fraction.padEnd(3,'0')}
export function m74AssetId(value:unknown):string{m74Require(typeof value==='string');const normalized=(value as string).trim().toUpperCase();m74Require(/^[A-Z0-9][A-Z0-9._-]{0,63}$/.test(normalized),'Vehicle asset ID must use 1–64 ASCII letters, numbers, period, underscore or hyphen.');return normalized}

export function validateM74Save(value:unknown):M74SaveInput{
 m74Keys(value,['profile','binding','period','vehicle','quantityGallons','distanceMiles','fuelStatement','mileageStatement','fuelManualConfirmation','mileageManualConfirmation','fuelDiscrepancyReason','mileageDiscrepancyReason','zeroReason','expectedVersionId','expectedVersionSha256','correctionReason','idempotencyKey'])
 const v=structuredClone(value) as M74SaveInput
 m74Keys(v.binding,['coverageVersionId','coverageVersionSha256','entityId','facilityId','sourceId','boundaryDecisionId']);for(const [key,item] of Object.entries(v.binding))m74Require(key.endsWith('Sha256')?m71HashString(item):m71Uuid(item))
 m74Keys(v.period,['start','endExclusive'])
 m74Keys(v.vehicle,['assetId','vehicleClass','classificationBasis','modelYear','fuel','controlBasis'])
 m74Require(v.profile===M74_PROFILE&&m74CanonicalJson(v.period)===m74CanonicalJson(M74_PERIOD)&&v.vehicle.vehicleClass==='Medium- and Heavy-Duty Vehicles'&&Number.isInteger(v.vehicle.modelYear)&&v.vehicle.modelYear>=2007&&v.vehicle.modelYear<=2022&&v.vehicle.fuel==='Fossil Diesel'&&v.vehicle.controlBasis==='owned_operational_control_full_year'&&typeof v.fuelManualConfirmation==='boolean'&&typeof v.mileageManualConfirmation==='boolean'&&m71Uuid(v.idempotencyKey))
 v.vehicle={...v.vehicle,assetId:m74AssetId(v.vehicle.assetId),classificationBasis:m74Text(v.vehicle.classificationBasis,500)}
 v.quantityGallons=v.quantityGallons===null?null:m74Quantity(v.quantityGallons)
 v.distanceMiles=v.distanceMiles===null?null:m74Quantity(v.distanceMiles)
 if(v.fuelStatement!==null){m74Keys(v.fuelStatement,['issuer','reference','statedQuantityGallons','description','consumptionBasis']);m74Require(v.fuelStatement.consumptionBasis==='dedicated_vehicle_consumed_no_adjustments');v.fuelStatement={...v.fuelStatement,issuer:m74Text(v.fuelStatement.issuer,120),reference:m74Text(v.fuelStatement.reference,120),statedQuantityGallons:m74Quantity(v.fuelStatement.statedQuantityGallons),description:m74Text(v.fuelStatement.description,2000)}}
 if(v.mileageStatement!==null){m74Keys(v.mileageStatement,['issuer','reference','statedDistanceMiles','description','distanceBasis']);m74Require(v.mileageStatement.distanceBasis==='dedicated_vehicle_annual_distance');v.mileageStatement={...v.mileageStatement,issuer:m74Text(v.mileageStatement.issuer,120),reference:m74Text(v.mileageStatement.reference,120),statedDistanceMiles:m74Quantity(v.mileageStatement.statedDistanceMiles),description:m74Text(v.mileageStatement.description,2000)}}
 v.fuelDiscrepancyReason=m74NullableText(v.fuelDiscrepancyReason);v.mileageDiscrepancyReason=m74NullableText(v.mileageDiscrepancyReason);v.zeroReason=m74NullableText(v.zeroReason);v.correctionReason=m74NullableText(v.correctionReason)
 if(v.expectedVersionId===null)m74Require(v.expectedVersionSha256===null&&v.correctionReason===null);else m74Require(m71Uuid(v.expectedVersionId)&&m71HashString(v.expectedVersionSha256)&&v.correctionReason!==null)
 return v
}

export function validateM74Review(value:unknown):M74ReviewInput{m74Keys(value,['versionId','expectedVersionSha256','decision','note','acknowledgedLimitations','idempotencyKey']);const v=structuredClone(value) as M74ReviewInput;m74Require(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71Uuid(v.idempotencyKey)&&['accepted_bounded_internal','changes_requested'].includes(v.decision)&&m74CanonicalJson(v.acknowledgedLimitations)===m74CanonicalJson(M74_LIMITATIONS));v.note=m74Text(v.note);return v}
export function validateM74Report(value:unknown):M74ReportInput{m74Keys(value,['versionId','expectedVersionSha256','expectedDecisionId','expectedDecisionSha256','idempotencyKey']);const v=value as M74ReportInput;m74Require(m71Uuid(v.versionId)&&m71HashString(v.expectedVersionSha256)&&m71Uuid(v.idempotencyKey)&&(v.expectedDecisionId===null?v.expectedDecisionSha256===null:m71Uuid(v.expectedDecisionId)&&m71HashString(v.expectedDecisionSha256)));return structuredClone(v)}
export function m74Activity(value:M74SaveInput):M74Activity{const {expectedVersionId:_,expectedVersionSha256:__,correctionReason:___,idempotencyKey:____,...activity}=value;return activity}

export function deriveM74ActivityStatus(activity:M74Activity):M74ActivityStatus{
 const dimension=(quantity:string|null,statement:object|null,confirmed:boolean,stated:string|null):M74ActivityStatus['fuel']=>quantity===null?'missing':statement===null?'evidence_missing':!confirmed?'unconfirmed':quantity!==stated?'discrepancy':quantity==='0.000'?'explicit_zero':'entered'
 return {fuel:dimension(activity.quantityGallons,activity.fuelStatement,activity.fuelManualConfirmation,activity.fuelStatement?.statedQuantityGallons??null),mileage:dimension(activity.distanceMiles,activity.mileageStatement,activity.mileageManualConfirmation,activity.mileageStatement?.statedDistanceMiles??null)}
}
export function m74CanCalculate(activity:M74Activity):boolean{
 const gallons=activity.quantityGallons,miles=activity.distanceMiles,fuel=activity.fuelStatement,mileage=activity.mileageStatement
 if(gallons===null||miles===null||fuel===null||mileage===null||!activity.fuelManualConfirmation||!activity.mileageManualConfirmation)return false
 if(gallons!==fuel.statedQuantityGallons&&!activity.fuelDiscrepancyReason)return false
 if(miles!==mileage.statedDistanceMiles&&!activity.mileageDiscrepancyReason)return false
 const gallonsZero=gallons==='0.000',milesZero=miles==='0.000'
 if(gallonsZero!==milesZero)return false
 if(gallonsZero)return fuel.statedQuantityGallons==='0.000'&&mileage.statedDistanceMiles==='0.000'&&Boolean(activity.zeroReason)
 return true
}
export function deriveM74Findings(activity:M74Activity):M74Finding[]{
 const findings:M74Finding[]=[{code:'scope1_incomplete',message:'This vehicle mobile-combustion subtotal does not complete stationary, mobile, fugitive or process emissions.'},{code:'method_not_released',message:'Factors and method are development candidates; no reporting or assurance determination.'}]
 const status=deriveM74ActivityStatus(activity)
 if(activity.quantityGallons===null)findings.push({code:'fuel_activity_missing',message:'Consumed gallons are missing; no emissions were calculated.'})
 if(activity.distanceMiles===null)findings.push({code:'mileage_activity_missing',message:'Vehicle-miles are missing; no emissions were calculated.'})
 if(activity.fuelStatement===null)findings.push({code:'fuel_statement_missing',message:'No synthetic annual fuel statement is retained.'})
 if(activity.mileageStatement===null)findings.push({code:'mileage_statement_missing',message:'No synthetic annual mileage statement is retained.'})
 if(status.fuel==='unconfirmed')findings.push({code:'fuel_statement_unconfirmed',message:'The synthetic fuel assumptions have not been manually confirmed.'})
 if(status.mileage==='unconfirmed')findings.push({code:'mileage_statement_unconfirmed',message:'The synthetic mileage assumptions have not been manually confirmed.'})
 if(status.fuel==='discrepancy')findings.push({code:'fuel_activity_statement_discrepancy',message:'Entered and stated consumed gallons differ; the discrepancy remains unresolved.'})
 if(status.mileage==='discrepancy')findings.push({code:'mileage_activity_statement_discrepancy',message:'Entered and stated vehicle-miles differ; the discrepancy remains unresolved.'})
 if(activity.quantityGallons!==null&&activity.distanceMiles!==null&&(activity.quantityGallons==='0.000')!==(activity.distanceMiles==='0.000'))findings.push({code:'mixed_zero_contradiction',message:'Zero in only one activity dimension is outside this bounded method; no emissions were calculated.'})
 if(activity.quantityGallons==='0.000'&&activity.distanceMiles==='0.000'&&!m74CanCalculate(activity))findings.push({code:'unsupported_zero',message:'Zero activity needs matching zero statements, both confirmations and a no-operation/no-consumption reason.'})
 return findings
}

export function m74SourceChoices(version:M71Version):M74SourceChoice[]{const snapshot=version.snapshot,within=(item:{start:string;endExclusive:string})=>item.start===M74_PERIOD.start&&item.endExclusive===M74_PERIOD.endExclusive;return snapshot.sources.filter(item=>item.domain==='mobile_combustion').map(source=>{const entity=snapshot.entities.find(item=>item.id===source.entityId),facility=snapshot.facilities.find(item=>item.id===source.facilityId),boundary=snapshot.boundaryDecisions.find(item=>item.entityId===source.entityId&&within(item));const findings:M74Finding[]=[];const add=(message:string)=>findings.push({code:'source_ineligible',message});if(snapshot.consolidationApproach!=='operational_control'||!within(snapshot.period)||!entity||!facility||facility.entityId!==entity.id||entity.countryCode!=='US'||entity.regionCode!=='CA'||facility.countryCode!=='US'||facility.regionCode!=='CA'||!within(entity)||!within(facility)||!within(source))add('Selected source needs a full-year 2025 California operational-control entity and base facility.');const supportedRefs=(refs:{artifactId:string;expectedSha256:string;locator:string}[])=>refs.some(ref=>ref.artifactId===M71_ARTIFACT.id&&ref.expectedSha256===M71_EVIDENCE_SHA256&&ref.locator===M71_ARTIFACT.locator);if(!boundary||boundary.disposition!=='included_activity'||!boundary.reason?.trim()||!supportedRefs(boundary.evidenceRefs))add('Save the entity inclusion rationale and pinned fictional boundary reference first.');let id=entity?.id;const seen=new Set<string>();while(id){if(seen.has(id)){add('Boundary relationship cycle.');break}seen.add(id);const relationship=snapshot.relationships.find(item=>item.childEntityId===id);if(!relationship)break;if(!within(relationship)||relationship.ownershipPercent!=='100'||!relationship.controlFacts?.trim()||!supportedRefs(relationship.evidenceRefs))add('Every selected relationship requires full-year operational-control facts and fictional support.');id=relationship.parentEntityId}return {binding:{coverageVersionId:version.id,coverageVersionSha256:version.versionSha256,entityId:source.entityId,facilityId:source.facilityId??'',sourceId:source.id,boundaryDecisionId:boundary?.id??''},companyLabel:snapshot.companyLabel,entityLabel:entity?.legalName??'',facilityLabel:facility?.name??'',sourceLabel:source.name,eligible:findings.length===0,findings}})}
export function m74ResolveBinding(binding:M74BindingInput,coverage:M71Version){const choice=m74SourceChoices(coverage).find(item=>item.binding.sourceId===binding.sourceId);m74Require(choice?.eligible&&m74CanonicalJson(choice.binding)===m74CanonicalJson(binding),'The selected saved mobile source or boundary is not eligible.');return choice!}
export function m74FuelStatementText(activity:M74Activity,coverage:M71Version):string{m74Require(activity.fuelStatement!==null);const choice=m74ResolveBinding(activity.binding,coverage);return 'SYNTHETIC — NOT A FUEL RECEIPT OR INDEPENDENT MEASUREMENT\n'+m74CanonicalJson({profile:'m74-synthetic-fuel-statement-v1',companyLabel:choice.companyLabel,entityLabel:choice.entityLabel,facilityLabel:choice.facilityLabel,sourceLabel:choice.sourceLabel,binding:activity.binding,period:activity.period,vehicle:activity.vehicle,quantityUnit:'US_gallon',fuelComposition:'fossil_diesel_only',statement:activity.fuelStatement})+'\n'}
export function m74MileageStatementText(activity:M74Activity,coverage:M71Version):string{m74Require(activity.mileageStatement!==null);const choice=m74ResolveBinding(activity.binding,coverage);return 'SYNTHETIC — NOT AN ODOMETER RECORD OR INDEPENDENT MEASUREMENT\n'+m74CanonicalJson({profile:'m74-synthetic-mileage-statement-v1',companyLabel:choice.companyLabel,entityLabel:choice.entityLabel,facilityLabel:choice.facilityLabel,sourceLabel:choice.sourceLabel,binding:activity.binding,period:activity.period,vehicle:activity.vehicle,distanceUnit:'vehicle_mile',tripCoverage:'all_trip_locations_including_interstate',statement:activity.mileageStatement})+'\n'}
export const m74InputHashPayload=(version:Pick<M74Version,'activity'>)=>version.activity
export const m74ContentPayload=(version:Pick<M74Version,'activity'|'activityStatus'|'coverageVersion'|'fuelStatement'|'mileageStatement'|'calculation'|'findings'>)=>({activity:version.activity,activityStatus:version.activityStatus,coverageVersion:version.coverageVersion,fuelStatement:version.fuelStatement,mileageStatement:version.mileageStatement,calculation:version.calculation,findings:version.findings})
export const m74VersionHashPayload=(version:M74Version)=>({profile:M74_PROFILE,id:version.id,companyId:version.companyId,worksheetId:version.worksheetId,version:version.version,previousVersionId:version.previousVersionId,previousVersionSha256:version.previousVersionSha256,createdBy:version.createdBy,createdAt:version.createdAt,contributorIds:version.contributorIds,correctionReason:version.correctionReason,inputSha256:version.inputSha256,contentSha256:version.contentSha256})
export function m74ReviewHashPayload(companyId:string,review:M74Review){const {decisionSha256:_,...body}=review;return {profile:M74_PROFILE,companyId,...body}}
export function m74ReportHashPayload(report:M74Report){const {reportSha256:_,html:__,snapshotJson:___,...body}=report;return {profile:M74_PROFILE,...body}}
export function m74CalculationHashPayload(calculation:M74Calculation){const {resultSha256:_,...body}=calculation;return body}
export const m74Export=(version:M74Version)=>m74CanonicalJson({...version,review:null})

import type {M74Review,M74Version} from './m74-contract'
import {m74CanonicalJson} from './m74-validation'

export const M74_REPORT_TEMPLATE=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Synthetic vehicle mobile-combustion source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Vehicle mobile-combustion subtotal — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source, vehicle and activity</h2><dl>{{facts}}</dl><h2>Gas results and calculation trace</h2>{{calculation}}<h2>Supporting synthetic fuel statement</h2><dl>{{fuelStatement}}</dl><h2>Supporting synthetic mileage statement</h2><dl>{{mileageStatement}}</dl><h2>Method and provenance</h2><dl>{{method}}</dl><h2>Corporate coverage remains incomplete</h2><p>This report covers one bounded vehicle source. Other stationary, mobile, fugitive, process, facility and period sources remain unresolved or separately assessed. Combustion only; upstream fuel emissions are excluded.</p><ul>{{findings}}</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>{{snapshot}}</pre></details></body></html>`

export const m74ReportSnapshot=(version:M74Version,review:M74Review|null)=>({profile:'m74-mobile-source-report-v1' as const,version:{...version,review:null},review})
export function m74RenderReport(snapshot:ReturnType<typeof m74ReportSnapshot>):string{
 const version=snapshot.version,calculation=version.calculation,source=version.coverageVersion.snapshot.sources.find(item=>item.id===version.activity.binding.sourceId),facility=version.coverageVersion.snapshot.facilities.find(item=>item.id===version.activity.binding.facilityId),entity=version.coverageVersion.snapshot.entities.find(item=>item.id===version.activity.binding.entityId),boundary=version.coverageVersion.snapshot.boundaryDecisions.find(item=>item.id===version.activity.binding.boundaryDecisionId)
 const escape=(value:unknown)=>String(value??'Missing').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')
 const pair=(label:string,value:unknown)=>'<dt>'+label+'</dt><dd>'+escape(value)+'</dd>'
 const evidence=(kind:'fuel'|'mileage')=>{const statement=kind==='fuel'?version.fuelStatement:version.mileageStatement,input=kind==='fuel'?version.activity.fuelStatement:version.activity.mileageStatement;if(!statement||!input)return pair('Evidence','No supporting '+kind+' statement retained');return pair('Statement type','Synthetic human-entered '+kind+' statement')+pair('Issuer',input.issuer)+pair('Reference',input.reference)+pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')+pair(kind==='fuel'?'Stated consumed fuel (U.S. gallons)':'Stated distance (vehicle-miles)',kind==='fuel'?(input as NonNullable<typeof version.activity.fuelStatement>).statedQuantityGallons:(input as NonNullable<typeof version.activity.mileageStatement>).statedDistanceMiles)+pair('Description',input.description)+pair('Manual confirmation',kind==='fuel'?version.activity.fuelManualConfirmation:version.activity.mileageManualConfirmation)+pair('Retained statement locator',statement.locator)+pair('Statement SHA-256',statement.sha256)+pair('Statement byte length',statement.byteLength)}
 const method=calculation?.method
 const fields:Record<string,string>={
  facts:pair('Company',version.coverageVersion.snapshot.companyLabel)+pair('Entity',entity?.legalName)+pair('Boundary basis',boundary?.reason)+pair('Base facility',facility?.name)+pair('Source',source?.name)+pair('Reporting period','2025-01-01 through 2026-01-01 (exclusive)')+pair('All-trip location basis','All vehicle travel, including interstate trips')+pair('Coverage version',version.activity.binding.coverageVersionId)+pair('Source version',version.version)+pair('Vehicle asset ID',version.activity.vehicle.assetId)+pair('Vehicle class',version.activity.vehicle.vehicleClass)+pair('Classification basis',version.activity.vehicle.classificationBasis)+pair('Model year',version.activity.vehicle.modelYear)+pair('Fuel',version.activity.vehicle.fuel)+pair('Control basis',version.activity.vehicle.controlBasis)+pair('Entered consumed fuel (U.S. gallons)',version.activity.quantityGallons)+pair('Fuel statement amount (U.S. gallons)',version.activity.fuelStatement?.statedQuantityGallons)+pair('Fuel dimension status',version.activityStatus.fuel)+pair('Fuel discrepancy explanation',version.activity.fuelDiscrepancyReason??'Not applicable')+pair('Entered distance (vehicle-miles)',version.activity.distanceMiles)+pair('Mileage statement amount (vehicle-miles)',version.activity.mileageStatement?.statedDistanceMiles)+pair('Mileage dimension status',version.activityStatus.mileage)+pair('Mileage discrepancy explanation',version.activity.mileageDiscrepancyReason??'Not applicable')+pair('No-operation/no-consumption explanation',version.activity.zeroReason??'Not applicable')+pair('Exact vehicle mobile-combustion subtotal (kg CO2e)',calculation?.total.unrounded)+pair('Displayed vehicle mobile-combustion subtotal (kg CO2e)',calculation?.total.display)+pair('Review as captured',snapshot.review?.decision??'Unreviewed')+pair('Reviewer note',snapshot.review?.note??'Not yet reviewed')+pair('Review time',snapshot.review?.reviewedAt??'Not yet reviewed')+pair('Correction reason',version.correctionReason??'Not applicable'),
  calculation:calculation?'<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'+(['co2','ch4','n2o'] as const).map((key,index)=>'<tr><th>'+['CO2','CH4','N2O'][index]+'</th><td>'+escape(calculation.gasResults[key].mass)+' '+escape(calculation.gasResults[key].massUnit)+'</td><td>'+escape(calculation.gasResults[key].co2e)+'</td></tr>').join('')+'</tbody></table><p>CO2 uses consumed U.S. gallons. CH4 and N2O use vehicle-miles. Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>':'<p>Required compatible activity and evidence are incomplete or contradictory; no emissions total was calculated.</p>',
  fuelStatement:evidence('fuel'),
  mileageStatement:evidence('mileage'),
  method:method?pair('Method ID and version',method.id+' / '+method.version)+pair('Source',method.sourceTitle)+pair('Source edition','January 15, 2025')+pair('Workbook SHA-256',method.sourceSha256)+pair('Factor locators',method.factorCells.join(', '))+pair('GWP locators',method.gwpCells.join(', '))+pair('Note locators',method.noteCells.join(', '))+pair('Factor normalization','Published displayed decimals corroborated by the EPA 2025 PDF; XLSX binary tails are not used')+pair('CO2 factor',method.co2KgPerGallon+' kg CO2 per U.S. gallon')+pair('CH4 factor',method.ch4GramsPerMile+' g CH4 per vehicle-mile')+pair('N2O factor',method.n2oGramsPerMile+' g N2O per vehicle-mile')+pair('GWP basis',method.gwpAssessment+'; CH4 '+method.ch4Gwp+', N2O '+method.n2oGwp)+pair('Rights status',method.rights)+pair('Method status',method.status):pair('Method','No calculation was admitted; method remains a development candidate'),
  findings:[...new Set([...version.findings,...version.coverageVersion.findings].map(item=>item.message))].map(message=>'<li>'+escape(message)+'</li>').join(''),
  snapshot:escape(m74CanonicalJson(snapshot)),
 }
 return M74_REPORT_TEMPLATE.replace(/\{\{(facts|calculation|fuelStatement|mileageStatement|method|findings|snapshot)\}\}/g,(_,key:string)=>fields[key]!)
}

-- M74 additive source-scoped synthetic mobile-diesel workpapers. Earlier history remains intact.
create table neuvetra.mobile_diesel_heads(id uuid primary key,company_id uuid not null references neuvetra.companies(id),source_id uuid not null,asset_id text not null,vehicle_key text not null,version_id uuid,revision integer not null default 0,fuel_reference_key text,mileage_reference_key text,unique(id,company_id),unique(company_id,source_id),unique(company_id,vehicle_key));
create table neuvetra.mobile_diesel_fuel_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.mobile_diesel_mileage_statements(id uuid primary key,company_id uuid not null references neuvetra.companies(id),payload jsonb not null,statement_sha256 text not null,statement_text text not null,unique(id,company_id));
create table neuvetra.mobile_diesel_evidence_reservations(company_id uuid not null references neuvetra.companies(id),evidence_key text not null,worksheet_id uuid not null,statement_kind text not null check(statement_kind in('fuel','mileage')),created_at timestamptz not null,primary key(company_id,evidence_key));
create table neuvetra.mobile_diesel_versions(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version integer not null,previous_version_id uuid,coverage_version_id uuid not null,fuel_statement_id uuid,mileage_statement_id uuid,quantity_gallons numeric(15,3),distance_miles numeric(15,3),payload jsonb not null,input_sha256 text not null,content_sha256 text not null,version_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,export_text text not null,unique(id,company_id),unique(company_id,worksheet_id,version),foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id),foreign key(previous_version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id),foreign key(coverage_version_id,company_id) references neuvetra.corporate_inventory_versions(id,company_id),foreign key(fuel_statement_id,company_id) references neuvetra.mobile_diesel_fuel_statements(id,company_id),foreign key(mileage_statement_id,company_id) references neuvetra.mobile_diesel_mileage_statements(id,company_id));
alter table neuvetra.mobile_diesel_heads add foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id);
alter table neuvetra.mobile_diesel_evidence_reservations add foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id);
create table neuvetra.mobile_diesel_reviews(id uuid primary key,company_id uuid not null,version_id uuid not null,payload jsonb not null,decision_sha256 text not null,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null,unique(id,company_id),unique(company_id,version_id),foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id));
create table neuvetra.mobile_diesel_reports(id uuid primary key,company_id uuid not null,worksheet_id uuid not null,version_id uuid not null,decision_id uuid,payload jsonb not null,report_sha256 text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null,unique(id,company_id),foreign key(worksheet_id,company_id) references neuvetra.mobile_diesel_heads(id,company_id),foreign key(version_id,company_id) references neuvetra.mobile_diesel_versions(id,company_id),foreign key(decision_id,company_id) references neuvetra.mobile_diesel_reviews(id,company_id));
create unique index m74_report_state on neuvetra.mobile_diesel_reports(company_id,version_id,coalesce(decision_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table neuvetra.mobile_diesel_requests(company_id uuid not null references neuvetra.companies(id),idempotency_key uuid not null,actor_id uuid not null references auth.users(id),kind text not null check(kind in('save','review','report')),fingerprint text not null,record_id uuid not null,primary key(company_id,idempotency_key));
create table neuvetra.mobile_diesel_audit(id uuid primary key,company_id uuid not null references neuvetra.companies(id),record_id uuid not null,kind text not null check(kind in('save','review','report')),record_sha256 text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null,unique(company_id,kind,record_id));
do $$declare t text;begin foreach t in array array['mobile_diesel_heads','mobile_diesel_fuel_statements','mobile_diesel_mileage_statements','mobile_diesel_evidence_reservations','mobile_diesel_versions','mobile_diesel_reviews','mobile_diesel_reports','mobile_diesel_requests','mobile_diesel_audit'] loop
execute format('alter table neuvetra.%I enable row level security',t);execute format('alter table neuvetra.%I force row level security',t);execute format('revoke all on neuvetra.%I from public,authenticated,neuvetra_runtime',t);execute format('create policy m74_read on neuvetra.%I for select to neuvetra_runtime using(neuvetra.has_staging_access() and neuvetra.is_company_member(company_id))',t);execute format('grant select on neuvetra.%I to neuvetra_runtime',t);
if t<>'mobile_diesel_heads' then execute format('create trigger m74_immutable before update or delete on neuvetra.%I for each row execute function neuvetra.reject_inventory_history_mutation()',t);end if;end loop;end $$;
create function neuvetra.m74_text(v jsonb,maximum integer) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or length(s) not between 1 and maximum or s<>btrim(s) or s~U&'^[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]|[\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]$' or s<>normalize(s,NFC) or s~'[[:cntrl:]]' then raise exception 'invalid text' using errcode='22023';end if;return s;end $$;
create function neuvetra.m74_quantity(v jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s text:=v#>>'{}';begin if jsonb_typeof(v) is distinct from 'string' or s!~'^(0|[1-9][0-9]{0,11})\.[0-9]{3}$' then raise exception 'invalid quantity' using errcode='22023';end if;return s;end $$;
create function neuvetra.m74_exact(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select case when position('.' in v::text)>0 then rtrim(rtrim(v::text,'0'),'.') else v::text end$$;
create function neuvetra.m74_display(v numeric) returns text language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$with x as(select v*10000 n),r as(select trunc(n) q,n-trunc(n) f from x) select to_char((q+case when f>0.5 or(f=0.5 and mod(q,2)=1)then 1 else 0 end)/10000,'FM999999999999999999999990.0000') from r$$;
create function neuvetra.m74_activity_status(a jsonb) returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select jsonb_build_object('fuel',case when a->'quantityGallons'='null' then 'missing' when a->'fuelStatement'='null' then 'evidence_missing' when a->'fuelManualConfirmation'<>'true' then 'unconfirmed' when a->>'quantityGallons'<>a#>>'{fuelStatement,statedQuantityGallons}' then 'discrepancy' when a->>'quantityGallons'='0.000' then 'explicit_zero' else 'entered' end,'mileage',case when a->'distanceMiles'='null' then 'missing' when a->'mileageStatement'='null' then 'evidence_missing' when a->'mileageManualConfirmation'<>'true' then 'unconfirmed' when a->>'distanceMiles'<>a#>>'{mileageStatement,statedDistanceMiles}' then 'discrepancy' when a->>'distanceMiles'='0.000' then 'explicit_zero' else 'entered' end)$$;
create function neuvetra.m74_can_calculate(a jsonb) returns boolean language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select a->'quantityGallons'<>'null' and a->'distanceMiles'<>'null' and a->'fuelStatement'<>'null' and a->'mileageStatement'<>'null' and a->'fuelManualConfirmation'='true' and a->'mileageManualConfirmation'='true' and (a->>'quantityGallons'=a#>>'{fuelStatement,statedQuantityGallons}' or a->'fuelDiscrepancyReason'<>'null') and (a->>'distanceMiles'=a#>>'{mileageStatement,statedDistanceMiles}' or a->'mileageDiscrepancyReason'<>'null') and ((a->>'quantityGallons'<>'0.000' and a->>'distanceMiles'<>'0.000') or (a->>'quantityGallons'='0.000' and a->>'distanceMiles'='0.000' and a#>>'{fuelStatement,statedQuantityGallons}'='0.000' and a#>>'{mileageStatement,statedDistanceMiles}'='0.000' and a->'zeroReason'<>'null'))$$;
create function neuvetra.m74_findings(a jsonb) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare out jsonb:='[{"code":"scope1_incomplete","message":"This vehicle mobile-combustion subtotal does not complete stationary, mobile, fugitive or process emissions."},{"code":"method_not_released","message":"Factors and method are development candidates; no reporting or assurance determination."}]';s jsonb:=neuvetra.m74_activity_status(a);begin
if a->'quantityGallons'='null' then out:=out||'[{"code":"fuel_activity_missing","message":"Consumed gallons are missing; no emissions were calculated."}]';end if;if a->'distanceMiles'='null' then out:=out||'[{"code":"mileage_activity_missing","message":"Vehicle-miles are missing; no emissions were calculated."}]';end if;if a->'fuelStatement'='null' then out:=out||'[{"code":"fuel_statement_missing","message":"No synthetic annual fuel statement is retained."}]';end if;if a->'mileageStatement'='null' then out:=out||'[{"code":"mileage_statement_missing","message":"No synthetic annual mileage statement is retained."}]';end if;if s->>'fuel'='unconfirmed' then out:=out||'[{"code":"fuel_statement_unconfirmed","message":"The synthetic fuel assumptions have not been manually confirmed."}]';end if;if s->>'mileage'='unconfirmed' then out:=out||'[{"code":"mileage_statement_unconfirmed","message":"The synthetic mileage assumptions have not been manually confirmed."}]';end if;if s->>'fuel'='discrepancy' then out:=out||'[{"code":"fuel_activity_statement_discrepancy","message":"Entered and stated consumed gallons differ; the discrepancy remains unresolved."}]';end if;if s->>'mileage'='discrepancy' then out:=out||'[{"code":"mileage_activity_statement_discrepancy","message":"Entered and stated vehicle-miles differ; the discrepancy remains unresolved."}]';end if;if a->'quantityGallons'<>'null' and a->'distanceMiles'<>'null' and ((a->>'quantityGallons'='0.000')<>(a->>'distanceMiles'='0.000')) then out:=out||'[{"code":"mixed_zero_contradiction","message":"Zero in only one activity dimension is outside this bounded method; no emissions were calculated."}]';end if;if a->>'quantityGallons'='0.000' and a->>'distanceMiles'='0.000' and not neuvetra.m74_can_calculate(a) then out:=out||'[{"code":"unsupported_zero","message":"Zero activity needs matching zero statements, both confirmations and a no-operation/no-consumption reason."}]';end if;return out;end $$;
create function neuvetra.m74_coverage(target_company uuid,b jsonb,current_required boolean default true) returns jsonb language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare cv record;s jsonb;e jsonb;f jsonb;src jsonb;bd jsonb;rel jsonb;node text;seen text[]:='{}';pair record;begin
perform neuvetra.m71_keys(b,'coverageVersionId,coverageVersionSha256,entityId,facilityId,sourceId,boundaryDecisionId');for pair in select key,value from jsonb_each(b) loop if jsonb_typeof(pair.value)<>'string' or (pair.value#>>'{}') !~ (case when pair.key='coverageVersionSha256' then '^[0-9a-f]{64}$' else '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' end) then raise exception 'invalid binding' using errcode='22023';end if;end loop;
select * into cv from neuvetra.corporate_inventory_versions where company_id=target_company and id=(b->>'coverageVersionId')::uuid;if not found or cv.version_sha256<>b->>'coverageVersionSha256' then raise exception 'coverage binding conflict' using errcode='23505';end if;
if current_required and not exists(select 1 from neuvetra.corporate_inventory_heads where company_id=target_company and version_id=cv.id) then raise exception 'coverage changed' using errcode='23505';end if;
s:=cv.payload->'snapshot';perform neuvetra.m71_snapshot(s,null);if neuvetra.m67_hash(s)<>cv.content_sha256 or neuvetra.m67_hash((cv.payload-'snapshot'-'versionSha256')||jsonb_build_object('profile','synthetic-corporate-coverage-v1'))<>cv.version_sha256 or cv.export_text<>neuvetra.m67_canonical(cv.payload||jsonb_build_object('findings',neuvetra.m71_findings(s),'synthetic',true,'corporateCompleteness','incomplete','releaseEligible',false,'assurance','none','emissionsTotals',null,'review',null)) then raise exception 'coverage integrity failure' using errcode='22023';end if;
select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=b->>'entityId';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=b->>'facilityId';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=b->>'sourceId';select x into bd from jsonb_array_elements(s->'boundaryDecisions')x where x->>'id'=b->>'boundaryDecisionId';
if s->>'consolidationApproach'<>'operational_control' or e is null or f is null or src is null or bd is null or src->>'domain'<>'mobile_combustion' or src->>'entityId'<>e->>'id' or src->>'facilityId'<>f->>'id' or f->>'entityId'<>e->>'id' or bd->>'entityId'<>e->>'id' or e->>'countryCode'<>'US' or e->>'regionCode' is distinct from 'CA' or f->>'countryCode'<>'US' or f->>'regionCode' is distinct from 'CA' or bd->>'disposition'<>'included_activity' or bd->'reason'='null' or jsonb_array_length(bd->'evidenceRefs')=0 then raise exception 'source ineligible' using errcode='22023';end if;
for pair in select value from jsonb_array_elements(jsonb_build_array(e,f,src,bd))loop if pair.value->>'start'<>'2025-01-01' or pair.value->>'endExclusive'<>'2026-01-01' then raise exception 'unsupported period' using errcode='22023';end if;end loop;
node:=e->>'id';loop if node=any(seen) then raise exception 'relationship cycle' using errcode='22023';end if;seen:=array_append(seen,node);select x into rel from jsonb_array_elements(s->'relationships')x where x->>'childEntityId'=node;exit when rel is null;if rel->>'start'<>'2025-01-01' or rel->>'endExclusive'<>'2026-01-01' or rel->>'ownershipPercent' is distinct from '100' or rel->'controlFacts'='null' or jsonb_array_length(rel->'evidenceRefs')=0 then raise exception 'control basis incomplete' using errcode='22023';end if;node:=rel->>'parentEntityId';end loop;
return cv.export_text::jsonb;end $$;
create function neuvetra.m74_validate_request(r jsonb) returns void language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare a jsonb;k text;begin
perform neuvetra.m71_keys(r,'profile,binding,period,vehicle,quantityGallons,distanceMiles,fuelStatement,mileageStatement,fuelManualConfirmation,mileageManualConfirmation,fuelDiscrepancyReason,mileageDiscrepancyReason,zeroReason,expectedVersionId,expectedVersionSha256,correctionReason,idempotencyKey');
if r->>'profile' is distinct from 'synthetic-mobile-diesel-v1' or r->'period' is distinct from '{"start":"2025-01-01","endExclusive":"2026-01-01"}'::jsonb or jsonb_typeof(r->'fuelManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'mileageManualConfirmation') is distinct from 'boolean' or jsonb_typeof(r->'idempotencyKey') is distinct from 'string' or r->>'idempotencyKey'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'invalid profile' using errcode='22023';end if;
a:=r->'vehicle';perform neuvetra.m71_keys(a,'assetId,vehicleClass,classificationBasis,modelYear,fuel,controlBasis');if jsonb_typeof(a->'assetId')<>'string' or a->>'assetId'!~'^[A-Z0-9][A-Z0-9._-]{0,63}$' or a->>'vehicleClass'<>'Medium- and Heavy-Duty Vehicles' or jsonb_typeof(a->'modelYear')<>'number' or a->>'modelYear'!~'^(200[7-9]|201[0-9]|202[0-2])$' or a->>'fuel'<>'Fossil Diesel' or a->>'controlBasis'<>'owned_operational_control_full_year' then raise exception 'unsupported vehicle' using errcode='22023';end if;perform neuvetra.m74_text(a->'classificationBasis',500);
foreach k in array array['fuelDiscrepancyReason','mileageDiscrepancyReason','zeroReason','correctionReason']loop if r->k<>'null' then perform neuvetra.m74_text(r->k,500);end if;end loop;
if r->'expectedVersionId'='null' then if r->'expectedVersionSha256'<>'null' or r->'correctionReason'<>'null' then raise exception 'initial binding invalid' using errcode='22023';end if;else if jsonb_typeof(r->'expectedVersionId')<>'string' or r->>'expectedVersionId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or jsonb_typeof(r->'expectedVersionSha256')<>'string' or r->>'expectedVersionSha256'!~'^[0-9a-f]{64}$' or r->'correctionReason'='null' then raise exception 'correction binding invalid' using errcode='22023';end if;end if;
if r->'quantityGallons'<>'null' then perform neuvetra.m74_quantity(r->'quantityGallons');end if;if r->'distanceMiles'<>'null' then perform neuvetra.m74_quantity(r->'distanceMiles');end if;
if r->'fuelStatement'<>'null' then a:=r->'fuelStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedQuantityGallons,description,consumptionBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedQuantityGallons');perform neuvetra.m74_text(a->'description',2000);if a->>'consumptionBasis'<>'dedicated_vehicle_consumed_no_adjustments' then raise exception 'fuel basis invalid' using errcode='22023';end if;end if;
if r->'mileageStatement'<>'null' then a:=r->'mileageStatement';perform neuvetra.m71_keys(a,'issuer,reference,statedDistanceMiles,description,distanceBasis');perform neuvetra.m74_text(a->'issuer',120);perform neuvetra.m74_text(a->'reference',120);perform neuvetra.m74_quantity(a->'statedDistanceMiles');perform neuvetra.m74_text(a->'description',2000);if a->>'distanceBasis'<>'dedicated_vehicle_annual_distance' then raise exception 'distance basis invalid' using errcode='22023';end if;end if;end $$;
create function neuvetra.m74_statement(a jsonb,coverage jsonb,kind text) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare s jsonb:=coverage->'snapshot';e jsonb;f jsonb;src jsonb;body jsonb;begin select x into e from jsonb_array_elements(s->'entities')x where x->>'id'=a#>>'{binding,entityId}';select x into f from jsonb_array_elements(s->'facilities')x where x->>'id'=a#>>'{binding,facilityId}';select x into src from jsonb_array_elements(s->'sources')x where x->>'id'=a#>>'{binding,sourceId}';if kind='fuel' then body:=jsonb_build_object('profile','m74-synthetic-fuel-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityUnit','US_gallon','fuelComposition','fossil_diesel_only','statement',a->'fuelStatement');return 'SYNTHETIC — NOT A FUEL RECEIPT OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(body)||chr(10);elsif kind='mileage' then body:=jsonb_build_object('profile','m74-synthetic-mileage-statement-v1','companyLabel',s->'companyLabel','entityLabel',e->'legalName','facilityLabel',f->'name','sourceLabel',src->'name','binding',a->'binding','period',a->'period','vehicle',a->'vehicle','distanceUnit','vehicle_mile','tripCoverage','all_trip_locations_including_interstate','statement',a->'mileageStatement');return 'SYNTHETIC — NOT AN ODOMETER RECORD OR INDEPENDENT MEASUREMENT'||chr(10)||neuvetra.m67_canonical(body)||chr(10);else raise exception 'invalid statement kind' using errcode='22023';end if;end $$;

create function neuvetra.m74_method() returns jsonb language sql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$select '{"id":"mobile-diesel-combustion","version":"m74-development-v1","engineSha256":"1dc0bb7249d91e854004a8cadd34068be3fc03ecdd6e10b4cf297d375d7f52a6","sourceSha256":"43afb91d79b2ae765b3a447549d9e1021a144a407cec5eb804be9fcf69a668a7","factorSha256":"416931c40b347f1e22e9d4019ca1c28bd27ce40d7c16a3beeac3dadbbb783187","gwpSha256":"c151f9b90b23eba7ee9d36dd57a851ecf7a6f200c915579819b683d2b3b3c1c7","sourceTitle":"EPA GHG Emission Factors Hub 2025","sourceSheet":"Emission Factors Hub","factorCells":["C103:E103","C107:E107","C255:G256"],"gwpCells":["E523:E526"],"noteCells":["F3","F248:G248","C255:D256"],"co2KgPerGallon":"10.21","ch4GramsPerMile":"0.0095","n2oGramsPerMile":"0.0431","ch4Gwp":"28","n2oGwp":"265","gwpAssessment":"IPCC AR5 100-year","status":"development_candidate_not_released","releaseEligible":false,"rights":"unresolved_for_factor_release"}'::jsonb$$;
create function neuvetra.m74_calculation(a jsonb,fuel_hash text,mileage_hash text) returns jsonb language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare gallons numeric;miles numeric;co2 numeric;ch4 numeric;n2o numeric;ch4e numeric;n2oe numeric;total numeric;i jsonb;body jsonb;begin
if not neuvetra.m74_can_calculate(a) then return 'null'::jsonb;end if;gallons:=(a->>'quantityGallons')::numeric;miles:=(a->>'distanceMiles')::numeric;co2:=gallons*10.21;ch4:=miles*0.0095/1000;n2o:=miles*0.0431/1000;ch4e:=ch4*28;n2oe:=n2o*265;total:=co2+ch4e+n2oe;
i:=jsonb_build_object('binding',a->'binding','period',a->'period','vehicle',a->'vehicle','quantityGallons',a->'quantityGallons','quantityUnit','US_gallon','distanceMiles',a->'distanceMiles','distanceUnit','vehicle_mile','fuelStatementSha256',fuel_hash,'mileageStatementSha256',mileage_hash);
body:=jsonb_build_object('profile','m74-decimal-result-v1','input',i,'inputSha256',neuvetra.m67_hash(i),'method',neuvetra.m74_method(),'gasResults',jsonb_build_object('co2',jsonb_build_object('mass',neuvetra.m74_exact(co2),'massUnit','kg CO2','co2e',neuvetra.m74_exact(co2),'co2eUnit','kg CO2e'),'ch4',jsonb_build_object('mass',neuvetra.m74_exact(ch4),'massUnit','kg CH4','co2e',neuvetra.m74_exact(ch4e),'co2eUnit','kg CO2e'),'n2o',jsonb_build_object('mass',neuvetra.m74_exact(n2o),'massUnit','kg N2O','co2e',neuvetra.m74_exact(n2oe),'co2eUnit','kg CO2e')),'total',jsonb_build_object('unrounded',neuvetra.m74_exact(total),'display',neuvetra.m74_display(total),'unit','kg CO2e','rounding','half_even_4dp'));
return body||jsonb_build_object('resultSha256',neuvetra.m67_hash(body));end $$;
create function neuvetra.m74_capacity(target_company uuid,new_bytes integer) returns void language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare used_bytes bigint;begin
select coalesce((select sum(octet_length(convert_to(export_text,'utf8'))+4096) from neuvetra.mobile_diesel_versions where company_id=target_company),0)+coalesce((select sum(octet_length(convert_to(payload::text,'utf8'))) from neuvetra.mobile_diesel_reports where company_id=target_company),0) into used_bytes;
if used_bytes+new_bytes>3800000 then raise exception 'history bytes limit' using errcode='54001';end if;end $$;
create function neuvetra.save_mobile_diesel(target_company uuid,target_worksheet uuid,request jsonb,calculation jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();head neuvetra.mobile_diesel_heads%rowtype;prior neuvetra.mobile_diesel_versions%rowtype;old neuvetra.mobile_diesel_requests%rowtype;reservation neuvetra.mobile_diesel_evidence_reservations%rowtype;coverage jsonb;a jsonb;fuel_statement jsonb:='null';mileage_statement jsonb:='null';fuel_id uuid;mileage_id uuid;fuel_text text;mileage_text text;fuel_hash text;mileage_hash text;fuel_key text;mileage_key text;vehicle_key text;expected_calc jsonb;body jsonb;v jsonb;contributors jsonb;fingerprint text;input_hash text;content_hash text;version_hash text;frozen text;new_id uuid:=gen_random_uuid();captured timestamptz;begin
if not neuvetra.m71_lock(target_company,true) then raise exception 'forbidden' using errcode='42501';end if;perform id from neuvetra.companies where id=target_company for update;perform id from neuvetra.corporate_inventory_heads where company_id=target_company for update;
perform neuvetra.m74_validate_request(request);fingerprint:=neuvetra.m67_hash(jsonb_build_object('operation','save','actor',actor,'companyId',target_company,'worksheetId',target_worksheet,'request',request-'idempotencyKey'));select * into old from neuvetra.mobile_diesel_requests where company_id=target_company and idempotency_key=(request->>'idempotencyKey')::uuid;if found then if old.fingerprint<>fingerprint or old.kind<>'save' or old.actor_id<>actor then raise exception 'idempotency conflict' using errcode='23505';end if;return old.record_id;end if;
