create function neuvetra.m74_render_report(snapshot jsonb) returns text language plpgsql immutable set search_path=pg_catalog,neuvetra,pg_temp as $$declare v jsonb:=snapshot->'version';c jsonb:=v->'calculation';m jsonb:=c->'method';src jsonb;f jsonb;entity jsonb;boundary jsonb;facts text;calc text;fuel text;mileage text;method text;findings text;begin
