 CO2e)',c#>>'{total,unrounded}')||neuvetra.m74_pair('Displayed vehicle mobile-combustion subtotal (kg CO2e)',c#>>'{total,display}')||neuvetra.m74_pair('Review as captured',coalesce(snapshot#>>'{review,decision}','Unreviewed'))||neuvetra.m74_pair('Reviewer note',coalesce(snapshot#>>'{review,note}','Not yet reviewed'))||neuvetra.m74_pair('Review time',coalesce(snapshot#>>'{review,reviewedAt}','Not yet reviewed'))||neuvetra.m74_pair('Correction reason',coalesce(v->>'correctionReason','Not applicable'));
if c='null' then calc:='<p>Required compatible activity and evidence are incomplete or contradictory; no emissions total was calculated.</p>';method:=neuvetra.m74_pair('Method','No calculation was admitted; method remains a development candidate');else calc:='<table><thead><tr><th>Gas</th><th>Mass</th><th>kg CO2e</th></tr></thead><tbody>'||(select string_agg('<tr><th>'||label||'</th><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'mass'])||' '||neuvetra.m74_escape(c#>>array['gasResults',key,'massUnit'])||'</td><td>'||neuvetra.m74_escape(c#>>array['gasResults',key,'co2e'])||'</td></tr>','' order by ord)from(values('co2','CO2',1),('ch4','CH4',2),('n2o','N2O',3))gases(key,label,ord))||'</tbody></table><p>CO2 uses consumed U.S. gallons. CH4 and N2O use vehicle-miles. Only the displayed total is rounded to four decimal places, using half-even rounding. Gas values and the exact total retain full precision.</p>';method:=neuvetra.m74_pair('Method ID and version',(m->>'id')||' / '||(m->>'version'))||neuvetra.m74_pair('Source',m->>'sourceTitle')||neuvetra.m74_pair('Source edition','January 15, 2025')||neuvetra.m74_pair('Workbook SHA-256',m->>'sourceSha256')||neuvetra.m74_pair('Factor locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'factorCells')with ordinality x(value,ord)))||neuvetra.m74_pair('GWP locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'gwpCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Note locators',(select string_agg(value,', ' order by ord)from jsonb_array_elements_text(m->'noteCells')with ordinality x(value,ord)))||neuvetra.m74_pair('Factor normalization','Published displayed decimals corroborated by the EPA 2025 PDF; XLSX binary tails are not used')||neuvetra.m74_pair('CO2 factor',(m->>'co2KgPerGallon')||' kg CO2 per U.S. gallon')||neuvetra.m74_pair('CH4 factor',(m->>'ch4GramsPerMile')||' g CH4 per vehicle-mile')||neuvetra.m74_pair('N2O factor',(m->>'n2oGramsPerMile')||' g N2O per vehicle-mile')||neuvetra.m74_pair('GWP basis',(m->>'gwpAssessment')||'; CH4 '||(m->>'ch4Gwp')||', N2O '||(m->>'n2oGwp'))||neuvetra.m74_pair('Rights status',m->>'rights')||neuvetra.m74_pair('Method status',m->>'status');end if;
fuel:=case when v->'fuelStatement'='null' then neuvetra.m74_pair('Evidence','No supporting fuel statement retained') else neuvetra.m74_pair('Statement type','Synthetic human-entered fuel statement')||neuvetra.m74_pair('Issuer',v#>>'{activity,fuelStatement,issuer}')||neuvetra.m74_pair('Reference',v#>>'{activity,fuelStatement,reference}')||neuvetra.m74_pair('Annual period','2025-01-01 through 2026-01-01 (exclusive)')||neuvetra.m74_pair('Stated consumed fuel (U.S. gallons)',v#>>'{activity,fuelStatement,statedQuantityGallons}')||neuvetra.m74_pair('Description',v#>>'{activity,fuelStatement,description}')||neuvetra.m74_pair('Manual confirmation',v#>>'{activity,fuelManualConfirmation}')||neuvetra.m74_pair('Retained statement locator',v#>>'{fuelStatement,locator}')||neuvetra.m74_pair('Statement SHA-256',v#>>'{fuelStatement,sha256}')||neuvetra.m74_pair('Statement byte length',v#>>'{fuelStatement,byteLength}') end;
