return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''"><title>Synthetic vehicle mobile-combustion source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Vehicle mobile-combustion subtotal — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source, vehicle and activity</h2><dl>'||facts||'</dl><h2>Gas results and calculation trace</h2>'||calc||'<h2>Supporting synthetic fuel statement</h2><dl>'||fuel||'</dl><h2>Supporting synthetic mileage statement</h2><dl>'||mileage||'</dl><h2>Method and provenance</h2><dl>'||method||'</dl><h2>Corporate coverage remains incomplete</h2><p>This report covers one bounded vehicle source. Other stationary, mobile, fugitive, process, facility and period sources remain unresolved or separately assessed. Combustion only; upstream fuel emissions are excluded.</p><ul>'||findings||'</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>'||neuvetra.m74_escape(neuvetra.m67_canonical(snapshot))||'</pre></details></body></html>';end $$;
create function neuvetra.create_mobile_diesel_report(target_company uuid,target_worksheet uuid,request jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,neuvetra,pg_temp as $$declare actor uuid:=auth.uid();v record;decision record;old record;new_id uuid:=gen_random_uuid();captured timestamptz;fingerprint text;snapshot jsonb;snapshot_text text;html text;body jsonb;digest text;begin
