        {(["fuel", "mileage"] as const).map(kind => { const statement = kind === "fuel" ? selected.fuelStatement : selected.mileageStatement; if (!statement) return null; return <details key={kind}><summary>{kind === "fuel" ? "Fuel" : "Mileage"} supporting evidence</summary><p>Fictional annual statement · {statement.input.issuer} · {statement.input.reference}</p><p>{statement.input.description}</p><p>Manual confirmation: {(kind === "fuel" ? selected.activity.fuelManualConfirmation : selected.activity.mileageManualConfirmation) ? "Confirmed" : "Not confirmed"}</p><pre>{statement.text}</pre><p className="worksheet-fingerprint">{statement.sha256}</p><button disabled={busy} onClick={() => void action(`statement-${kind}`, async () => { if (workspaceId) { const text = await mobileStatementDownload(actor, workspaceId, stream.worksheetId, selected, kind); if (active()) download(text, `mobile-${kind}-${statement.id}.txt`, "text/plain;charset=utf-8") } }, selected.id)}>Download {kind} statement</button></details> })}
        <details><summary>Version fingerprint</summary><p className="worksheet-fingerprint">{selected.versionSha256}</p><p>Coverage version: {selected.activity.binding.coverageVersionId}</p></details>
        <button disabled={busy} onClick={() => void action("export", async () => { if (workspaceId) { const text = await mobileExportRequest(actor, workspaceId, selected); if (active()) download(text, `mobile-diesel-version-${selected.version}.json`, "application/json") } }, selected.id)}>Download calculation record</button>{manager && <button disabled={busy} onClick={() => void createReport()}>Create vehicle report</button>}
      </article></>}
    {canReview && <form className="worksheet-card worksheet-form" onSubmit={e => { e.preventDefault(); void review() }}><h2>Review vehicle version {latest.version}</h2><fieldset disabled={busy}><label htmlFor="mobile-decision">Internal decision<select id="mobile-decision" value={decision} onChange={e => setDecision(e.target.value as typeof decision)}><option value="accepted_bounded_internal" disabled={!latest.calculation}>Accept for bounded internal use</option><option value="changes_requested">Request changes</option></select></label><label htmlFor="mobile-review-note">Review note<textarea id="mobile-review-note" required maxLength={500} value={reviewNote} onChange={e => setReviewNote(e.target.value)}/></label><ul>{M74_LIMITATIONS.map(l => <li key={l}>{words(l)}</li>)}</ul><label className="worksheet-check" htmlFor="mobile-review-ack"><input id="mobile-review-ack" type="checkbox" required checked={ack} onChange={e => setAck(e.target.checked)}/>I reviewed this exact vehicle version and acknowledge all listed limitations.</label><button type="submit" disabled={decision === "accepted_bounded_internal" && !latest.calculation}>Save internal vehicle review</button></fieldset></form>}
    {latest?.contributorIds.includes(actor.userId) && <p>A manager who has not contributed to this vehicle history or linked boundary must perform the internal review.</p>}
    {!editing && stream?.reports.filter(r => r.versionId === selected?.id).map(r => <article className="worksheet-card" key={r.id}><h2>Retained vehicle report</h2><p>{r.decisionId ? "Reviewed snapshot" : "Unreviewed snapshot"} · {r.createdAt}</p><div className="worksheet-report-actions"><button disabled={busy} onClick={() => void reportFile(r, "open")}>Open report</button><button disabled={busy} onClick={() => void reportFile(r, "print")}>Print report</button><button disabled={busy} onClick={() => void reportFile(r, "download")}>Download HTML</button></div><p className="worksheet-fingerprint">{r.htmlSha256}</p></article>)}
    <article className="worksheet-card"><h2>Corporate coverage remains incomplete</h2><p>This vehicle workpaper does not reconcile the fleet or complete stationary combustion, refrigerants, process emissions or corporate Scope 1. Scope 2, all 15 Scope 3 categories and applicable reporting requirements remain separate assessments.</p>{stream?.findings.map(f => <p key={f.code}>{f.message}</p>)}<details><summary>{register?.coverageFindings.length ?? 0} recorded open findings in current corporate coverage</summary><ul>{register?.coverageFindings.map((f, i) => <li key={`${f.code}:${i}`}>{f.message}</li>)}</ul></details></article>
    <p className="worksheet-footnote">Synthetic workpaper only. No released method, filing determination or external assurance.</p>
  </section>
}

import { useCallback, useEffect, useRef, useState, type FormEvent, type RefObject } from "react"
import type { HostedWorkspaceActor } from "@/lib/workspace-api"
import { corporateRegisterRequest, corporateSaveRequest, corporateReviewRequest, corporateExportRequest, syntheticCoverageReference } from "@/lib/m71-api"
import { createM71Seed, M71_MAX_VERSIONS, M71_ARTIFACT, M71_CATEGORIES, M71_LIMITATIONS, type M71Snapshot, type M71Register, type M71CoverageItem, type M71Disposition, type M71Version } from "../../../../packages/neuvetra-database/src/m71-contract"

const clone = <T,>(value:T):T => structuredClone(value)
const words = (value:string) => value.replace(/_/g, " ")
const dispositions:Record<M71Disposition,string> = {unassessed:"Not assessed",missing:"Missing",included_activity:"Proposed inclusion",included_estimate:"Estimate proposed",excluded:"Proposed exclusion",not_applicable:"Proposed not applicable"}
const domainName = (domain:string) => domain.startsWith("scope3_") ? `${domain.slice(7)}. ${M71_CATEGORIES[Number(domain.slice(7))-1]}` : ({stationary_combustion:"Stationary combustion",mobile_combustion:"Mobile combustion",process:"Process emissions",fugitive:"Fugitive emissions",electricity:"Purchased electricity",steam:"Purchased steam",heat:"Purchased heat",cooling:"Purchased cooling",location_based:"Location-based Scope 2 view",market_based:"Market-based Scope 2 view"}[domain]??words(domain))
const limits = ["Fictional data only", "Corporate inventory remains incomplete", "Methods are not released", "Reporting requirements are not determined", "No emissions totals are calculated", "No external assurance"]

function findingLabel(snapshot:M71Snapshot,id:string|null):string {
 if(!id)return "Company register"
 const entity=snapshot.entities.find(e=>e.id===id);if(entity)return entity.legalName
 const facility=snapshot.facilities.find(f=>f.id===id);if(facility)return facility.name
 const source=snapshot.sources.find(r=>r.id===id);if(source)return `${source.name} · ${snapshot.facilities.find(f=>f.id===source.facilityId)?.name??snapshot.entities.find(e=>e.id===source.entityId)?.legalName??"Operation"}`
 const decision=snapshot.boundaryDecisions.find(r=>r.id===id);if(decision)return `${snapshot.entities.find(e=>e.id===decision.entityId)?.legalName??"Entity"} boundary`
 const relationship=snapshot.relationships.find(r=>r.id===id);if(relationship)return `${snapshot.entities.find(e=>e.id===relationship.childEntityId)?.legalName??"Entity"} ownership and control`
 const row=snapshot.coverageItems.find(r=>r.id===id);if(row)return `${domainName(row.domain)}${row.sourceId?` · ${findingLabel(snapshot,row.sourceId)}`:" · Company-wide screening"}`
 return "Reporting requirement"
}

export function CorporateCoverageRegister({actor,workspaceId,headingRef}:{actor:HostedWorkspaceActor;workspaceId:string|null;headingRef:RefObject<HTMLHeadingElement|null>}) {
 const [saved,setSaved]=useState<M71Register|null>(null),[draft,setDraft]=useState<M71Snapshot>(()=>createM71Seed())
 const [panel,setPanel]=useState<"boundary"|"coverage"|"history">("boundary"),[selected,setSelected]=useState<string|null>(null)
 const [editing,setEditing]=useState(false),[reason,setReason]=useState(""),[busy,setBusy]=useState(true),[error,setError]=useState(false),[message,setMessage]=useState("Loading the saved company coverage…")
 const [historyId,setHistoryId]=useState(""),[reviewNote,setReviewNote]=useState(""),[reviewDecision,setReviewDecision]=useState<"accepted_bounded_internal"|"changes_requested">("accepted_bounded_internal"),[acknowledged,setAcknowledged]=useState(false)
 const [operation,setOperation]=useState({name:"",facility:"",country:"US",region:"CA"})
 const [gasSource,setGasSource]=useState({facilityId:"",name:""})
 const [mobileSource,setMobileSource]=useState({facilityId:"",name:""})
 const lifecycle=useRef({active:true}),lock=useRef(false),pending=useRef<{signature:string;key:string}|null>(null),initialActor=useRef(actor)
 const latest=saved?.versions[saved.versions.length-1],historical=saved?.versions.find(v=>v.id===historyId)??latest
 const manager=actor.role!=="member",canEdit=manager&&editing&&!busy
 const active=()=>lifecycle.current.active&&!actor.signal?.aborted
 const displayed=editing?draft:latest?.snapshot??draft
 const selectedItem=displayed.coverageItems.find(row=>row.id===selected)
 const accept=useCallback((register:M71Register)=>{setSaved(register);const last=register.versions[register.versions.length-1];setDraft(clone(last?.snapshot??createM71Seed()));setEditing(!last&&manager);setReason("");setHistoryId(last?.id??"");setReviewNote("");setAcknowledged(false)},[manager])
 useEffect(()=>{const state={active:true};lifecycle.current=state;const currentActor=initialActor.current;void(async()=>{try{if(!workspaceId){setMessage("No company workspace is assigned.");return}const register=await corporateRegisterRequest(currentActor,workspaceId);if(state.active&&!currentActor.signal?.aborted){accept(register);setMessage(register.versions.length?"Saved coverage loaded. Review unresolved findings before making a correction.":"Start with the fictional California company, then save its coverage register.")}}catch(e){if(state.active&&!currentActor.signal?.aborted){setError(true);setMessage(e instanceof Error?e.message:"Coverage is unavailable.")}}finally{if(state.active&&!currentActor.signal?.aborted)setBusy(false)}})();return()=>{state.active=false}},[workspaceId,accept])
 async function run(action:"refresh"|"save"|"review"){if(!workspaceId||lock.current||!active())return;lock.current=true;setBusy(true);setError(false);try{
  if(action==="save"){
   const effective={snapshot:draft,expectedVersionId:latest?.id??null,expectedVersionSha256:latest?.versionSha256??null,correctionReason:latest?reason:null};const signature=JSON.stringify({action,...effective});if(pending.current?.signature!==signature)pending.current={signature,key:crypto.randomUUID()}
   await corporateSaveRequest(actor,workspaceId,saved?.inventoryId??null,{...effective,idempotencyKey:pending.current.key})
  }else if(action==="review"&&latest&&saved?.inventoryId){
   const effective={versionId:latest.id,expectedVersionSha256:latest.versionSha256,decision:reviewDecision,note:reviewNote,acknowledgedLimitations:acknowledged?[...M71_LIMITATIONS]:[]};const signature=JSON.stringify({action,...effective});if(pending.current?.signature!==signature)pending.current={signature,key:crypto.randomUUID()}
   await corporateReviewRequest(actor,workspaceId,saved.inventoryId,{...effective,idempotencyKey:pending.current.key})
  }
  const register=await corporateRegisterRequest(actor,workspaceId);if(!active())return;accept(register);pending.current=null;setMessage(action==="save"?"Coverage version saved. Earlier versions and exports stay unchanged; review is still separate.":action==="review"?"Internal decision saved for this exact version. Coverage remains incomplete.":"Saved coverage refreshed.")
 }catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"Could not save coverage. Retry the same action or refresh.")}}finally{lock.current=false;if(active())setBusy(false)}}
 async function exportVersion(version:M71Version){if(!workspaceId||lock.current||!active())return;lock.current=true;setBusy(true);setError(false);try{const text=await corporateExportRequest(actor,workspaceId,version);if(!active())return;const url=URL.createObjectURL(new Blob([text],{type:"application/json"}));const link=document.createElement("a");link.href=url;link.download=`california-coverage-version-${version.version}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setMessage(`Version ${version.version} coverage downloaded. The frozen save snapshot does not include later review decisions.`)}catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"Export unavailable.")}}finally{lock.current=false;if(active())setBusy(false)}}
 function edit(mutator:(next:M71Snapshot)=>void){setDraft(old=>{const next=clone(old);mutator(next);return next})}
 async function attach(kind:"boundary"|"coverage"|"estimate",id:string,checked:boolean){if(!canEdit||lock.current||!active())return;lock.current=true;setBusy(true);try{const ref=checked?await syntheticCoverageReference():null;if(!active())return;edit(next=>{if(kind==="estimate"){const row=next.coverageItems.find(r=>r.id===id);if(row?.estimateBasis)row.estimateBasis.inputEvidenceRefs=ref?[ref]:[]}else{const row=kind==="boundary"?next.boundaryDecisions.find(r=>r.id===id):next.coverageItems.find(r=>r.id===id);if(row)row.evidenceRefs=ref?[ref]:[]}})}catch(e){if(active()){setError(true);setMessage(e instanceof Error?e.message:"Synthetic reference unavailable.")}}finally{lock.current=false;if(active())setBusy(false)}}
 function updateItem(patch:Partial<M71CoverageItem>){if(selected)edit(next=>{const row=next.coverageItems.find(r=>r.id===selected);if(row)Object.assign(row,patch)})}
 function addOperation(event:FormEvent){event.preventDefault();if(!canEdit)return;if(!operation.name.trim()||!operation.facility.trim()){setError(true);setMessage("Enter the operation and facility names.");return}edit(next=>{const entityId=crypto.randomUUID(),facilityId=crypto.randomUUID(),sourceId=crypto.randomUUID(),interval={...next.period};next.entities.push({id:entityId,legalName:operation.name,countryCode:operation.country,regionCode:operation.region||null,...interval,evidenceRefs:[]});next.facilities.push({id:facilityId,entityId,name:operation.facility,countryCode:operation.country,regionCode:operation.region||null,...interval,evidenceRefs:[]});next.sources.push({id:sourceId,entityId,facilityId,name:"Purchased electricity — assess activity",domain:"electricity",...interval,evidenceRefs:[]});next.boundaryDecisions.push({id:crypto.randomUUID(),entityId,disposition:"unassessed",reason:null,...interval,evidenceRefs:[]});next.relationships.push({id:crypto.randomUUID(),parentEntityId:next.entities[0]!.id,childEntityId:entityId,ownershipPercent:null,controlFacts:null,...interval,evidenceRefs:[]});next.coverageItems.push({id:crypto.randomUUID(),domain:"electricity",entityId,sourceId,...interval,disposition:"unassessed",activityDataState:"not_assessed",evidenceState:"missing",methodReadiness:"unsupported",reason:null,evidenceRefs:[],estimateBasis:null,quantity:null,unit:null})});setOperation({name:"",facility:"",country:"US",region:"CA"});setMessage("Operation added to this unsaved draft. Boundary, control and activity assessment remain open.")}
 function addGasSource(event:FormEvent){
  event.preventDefault();if(!canEdit||lock.current||!active())return
  const facility=draft.facilities.find(f=>f.id===gasSource.facilityId&&f.countryCode==="US"&&f.regionCode==="CA"&&f.start===draft.period.start&&f.endExclusive===draft.period.endExclusive)
  const name=gasSource.name.trim()
  if(!facility||!name){setError(true);setMessage("Select a full-year California facility and enter a fictional stationary source name.");return}
  const sourceId=crypto.randomUUID(),coverageId=crypto.randomUUID()
  edit(next=>{const interval={...next.period};next.sources.push({id:sourceId,entityId:facility.entityId,facilityId:facility.id,name,domain:"stationary_combustion",...interval,evidenceRefs:[]});next.coverageItems.push({id:coverageId,domain:"stationary_combustion",entityId:facility.entityId,sourceId,...interval,disposition:"missing",activityDataState:"missing",evidenceState:"missing",methodReadiness:"candidate",reason:null,evidenceRefs:[],estimateBasis:null,quantity:null,unit:null})})
  setGasSource({facilityId:"",name:""});setError(false);setMessage("Stationary source added to this unsaved draft. Record the entity's boundary rationale and fictional reference, then save the coverage version. Gas activity and evidence remain missing.")
 }
 function addMobileSource(event:FormEvent){
  event.preventDefault();if(!canEdit||lock.current||!active())return
  const facility=draft.facilities.find(f=>f.id===mobileSource.facilityId&&f.countryCode==="US"&&f.regionCode==="CA"&&f.start===draft.period.start&&f.endExclusive===draft.period.endExclusive)
  const name=mobileSource.name.trim()
