 for(const kind of ['fuel','mileage'] as const){
  const retained=kind==='fuel'?v.fuelStatement:v.mileageStatement
  const input=kind==='fuel'?v.activity.fuelStatement:v.activity.mileageStatement
  if(retained===null){if(input!==null)return fail();continue}
  m71Keys(retained,['id','profile','input','locator','text','sha256','byteLength'])
  const expected=kind==='fuel'?m74FuelStatementText(v.activity,v.coverageVersion):m74MileageStatementText(v.activity,v.coverageVersion)
  if(!m71Uuid(retained.id)||retained.profile!==`m74-synthetic-${kind}-statement-v1`||retained.locator!==`m74-${kind}-statement:${retained.id}:annual-activity`||!equal(retained.input,input)||retained.text!==expected||retained.byteLength!==new TextEncoder().encode(retained.text).length||await coverageSha256(retained.text)!==retained.sha256)return fail()
 }
 if(v.fuelStatement&&v.mileageStatement&&(v.fuelStatement.id===v.mileageStatement.id||v.fuelStatement.sha256===v.mileageStatement.sha256))return fail()
 if(!m74CanCalculate(v.activity)){if(v.calculation!==null)return fail()}else{
  const c=v.calculation;if(!c||!v.fuelStatement||!v.mileageStatement)return fail()
  m71Keys(c,['profile','input','inputSha256','method','gasResults','total','resultSha256'])
  m71Keys(c.input,['binding','period','vehicle','quantityGallons','quantityUnit','distanceMiles','distanceUnit','fuelStatementSha256','mileageStatementSha256'])
  const expectedInput={binding:v.activity.binding,period:v.activity.period,vehicle:v.activity.vehicle,quantityGallons:v.activity.quantityGallons,quantityUnit:'US_gallon',distanceMiles:v.activity.distanceMiles,distanceUnit:'vehicle_mile',fuelStatementSha256:v.fuelStatement.sha256,mileageStatementSha256:v.mileageStatement.sha256}
  if(c.profile!=='m74-decimal-result-v1'||!equal(c.input,expectedInput)||await hash(c.input)!==c.inputSha256||await hash(m74CalculationHashPayload(c))!==c.resultSha256)return fail()
  m71Keys(c.total,['unrounded','display','unit','rounding']);if(c.total.unit!=='kg CO2e'||c.total.rounding!=='half_even_4dp'||!/^\d+(?:\.\d+)?$/.test(c.total.unrounded)||!/^\d+\.\d{4}$/.test(c.total.display))return fail()
  m71Keys(c.gasResults,['co2','ch4','n2o']);for(const [name,gas] of Object.entries(c.gasResults)){m71Keys(gas,['mass','massUnit','co2e','co2eUnit']);if(gas.massUnit!=='kg '+name.toUpperCase()||gas.co2eUnit!=='kg CO2e'||!/^\d+(?:\.\d+)?$/.test(gas.mass)||!/^\d+(?:\.\d+)?$/.test(gas.co2e))return fail()}
