export async function mobileStatementDownload(a:HostedWorkspaceActor,c:string,w:string,v:M74Version,kind:'fuel'|'mileage'){
 const statement=kind==='fuel'?v.fuelStatement:v.mileageStatement
 if(v.companyId!==c||v.worksheetId!==w||!statement||!m71Uuid(w))return fail()
